\": \"https://registry.npmjs.org/undici-types/-/undici-types-6.21.0.tgz\",\r\n      \"integrity\": \"sha512-iwDZqg0QAGrg9Rav5H4n0M64c3mkR59cJ6wQp+7C4nI0gsmExaedaYLNO44eT4AtBBwjbTiGPMlt2Md0T9H9JQ==\",\r\n      \"dev\": true,\r\n      \"license\": \"MIT\"\r\n    },\r\n    \"node_modules/wsl-utils\": {\r\n      \"version\": \"0.1.0\",\r\n      \"resolved\": \"https://registry.npmjs.org/wsl-utils/-/wsl-utils-0.1.0.tgz\",\r\n      \"integrity\": \"sha512-h3Fbisa2nKGPxCpm89Hk33lBLsnaGBvctQopaBSOW/uIs6FTe1ATyAnKFJrzVs9vpGdsTe73WF3V4lIsk4Gacw==\",\r\n      \"license\": \"MIT\",\r\n      \"dependencies\": {\r\n        \"is-wsl\": \"^3.1.0\"\r\n      },\r\n      \"engines\": {\r\n        \"node\": \"\u003e=18\"\r\n      },\r\n      \"funding\": {\r\n        \"url\": \"https://github.com/sponsors/sindresorhus\"\r\n      }\r\n    }\r\n  }\r\n}\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"azure-keyvault-config-provider\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"TypeScript configuration provider backed by Azure Key Vault with caching and secret rotation\",\r\n  \"main\": \"dist/index.js\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc\",\r\n    \"start\": \"node dist/index.js\",\r\n    \"dev\": \"npm run build \u0026\u0026 npm start\",\r\n    \"clean\": \"rm -rf dist\"\r\n  },\r\n  \"keywords\": [\r\n    \"azure\",\r\n    \"keyvault\",\r\n    \"configuration\",\r\n    \"secrets\",\r\n    \"typescript\"\r\n  ],\r\n  \"author\": \"\",\r\n  \"license\": \"MIT\",\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.0.0\",\r\n    \"@azure/keyvault-secrets\": \"^4.8.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^20.10.0\",\r\n    \"typescript\": \"^5.3.0\"\r\n  }\r\n}\r\n\n```\n\n### src\\ConfigurationModule.ts\n```\nimport { DefaultAzureCredential } from '@azure/identity';\r\nimport { SecretClient } from '@azure/keyvault-secrets';\r\nimport { SecretProvider } from './SecretProvider';\r\nimport { CachedSecretProvider, CacheOptions } from './CachedSecretProvider';\r\n\r\nexport interface ConfigurationModuleOptions {\r\n  vaultUrl?: string;\r\n  cacheOptions?: CacheOptions;\r\n}\r\n\r\nexport class ConfigurationModule {\r\n  private secretClient: SecretClient;\r\n  private secretProvider: SecretProvider;\r\n  private cachedProvider: CachedSecretProvider;\r\n\r\n  constructor(options?: ConfigurationModuleOptions) {\r\n    // Get vault URL from environment variable or options\r\n    const vaultUrl = options?.vaultUrl || process.env.AZURE_KEYVAULT_URL;\r\n    \r\n    if (!vaultUrl) {\r\n      throw new Error(\r\n        'Vault URL not provided. Set AZURE_KEYVAULT_URL environment variable or pass vaultUrl in options.'\r\n      );\r\n    }\r\n\r\n    console.log(`Initializing configuration module with vault: ${vaultUrl}`);\r\n\r\n    // Use DefaultAzureCredential for managed identity authentication\r\n    // This works in Azure (managed identity) and locally (Azure CLI, VS Code, etc.)\r\n    const credential = new DefaultAzureCredential();\r\n\r\n    // Initialize the Key Vault client\r\n    this.secretClient = new SecretClient(vaultUrl, credential);\r\n\r\n    // Initialize provider layers\r\n    this.secretProvider = new SecretProvider(this.secretClient);\r\n    this.cachedProvider = new CachedSecretProvider(\r\n      this.secretProvider,\r\n      options?.cacheOptions\r\n    );\r\n\r\n    console.log('✓ Configuration module initialized');\r\n  }\r\n\r\n  /**\r\n   * Gets the cached secret provider for configuration access\r\n   */\r\n  getProvider(): CachedSecretProvider {\r\n    return this.cachedProvider;\r\n  }\r\n\r\n  /**\r\n   * Gets the underlying secret provider for direct Key Vault access\r\n   */\r\n  getSecretProvider(): SecretProvider {\r\n    return this.secretProvider;\r\n  }\r\n\r\n  /**\r\n   * Gets the raw Secret Client for advanced operations\r\n   */\r\n  getSecretClient(): SecretClient {\r\n    return this.secretClient;\r\n  }\r\n\r\n  /**\r\n   * Initializes the configuration by bulk-loading required secrets\r\n   * @param requiredSecrets Array of secret names to preload\r\n   * @param defaults Optional default values\r\n   */\r\n  async initialize(requiredSecrets: string[], defaults?: Record\u003cstring, string\u003e): Promise\u003cvoid\u003e {\r\n    console.log('Initializing configuration...');\r\n    await this.cachedProvider.bulkLoad(requiredSecrets, defaults);\r\n    console.log('✓ Configuration initialized');\r\n  }\r\n\r\n  /**\r\n   * Gets a configuration value\r\n   * @param key Configuration key (secret name)\r\n   * @param defaultValue Default value if not found\r\n   */\r\n  async getConfig(key: string, defaultValue?: string): Promise\u003cstring | null\u003e {\r\n    return await this.cachedProvider.get(key, defaultValue);\r\n  }\r\n\r\n  /**\r\n   * Refreshes a configuration value from Key Vault\r\n   * @param key Configuration key to refresh\r\n   */\r\n  async refreshConfig(key: string): Promise\u003cvoid\u003e {\r\n    await this.cachedProvider.refresh(key);\r\n  }\r\n\r\n  /**\r\n   * Checks for expiring secrets and returns their names\r\n   */\r\n  async checkHealth(): Promise\u003cstring[]\u003e {\r\n    return await this.cachedProvider.checkExpiringSecrets();\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { ConfigurationModule } from './ConfigurationModule';\r\nimport { SecretRotationHelper } from './SecretRotationHelper';\r\n\r\n/**\r\n * Demo script that showcases the full configuration provider flow\r\n */\r\nasync function main() {\r\n  console.log('='.repeat(70));\r\n  console.log('Azure Key Vault Configuration Provider Demo');\r\n  console.log('='.repeat(70));\r\n  console.log();\r\n\r\n  try {\r\n    // Step 1: Initialize the configuration module\r\n    console.log('Step 1: Initializing Configuration Module');\r\n    console.log('-'.repeat(70));\r\n    \r\n    const config = new ConfigurationModule({\r\n      cacheOptions: {\r\n        expiryWarningDays: 7,\r\n        autoRefreshNearExpiry: true,\r\n      },\r\n    });\r\n    console.log();\r\n\r\n    // Step 2: Bulk load configuration keys at startup\r\n    console.log('Step 2: Bulk Loading Configuration Keys');\r\n    console.log('-'.repeat(70));\r\n    \r\n    const requiredKeys = [\r\n      'DatabaseConnectionString',\r\n      'ApiKey',\r\n      'AppSecret',\r\n    ];\r\n\r\n    const defaults = {\r\n      DatabaseConnectionString: 'default-connection-string',\r\n      ApiKey: 'default-api-key',\r\n      AppSecret: 'default-app-secret',\r\n    };\r\n\r\n    await config.initialize(requiredKeys, defaults);\r\n    console.log();\r\n\r\n    // Step 3: Read configuration values from cache\r\n    console.log('Step 3: Reading Configuration from Cache');\r\n    console.log('-'.repeat(70));\r\n    \r\n    for (const key of requiredKeys) {\r\n      const value = await config.getConfig(key);\r\n      const metadata = config.getProvider().getMetadata(key);\r\n      \r\n      console.log(`${key}:`);\r\n      console.log(`  Value: ${value?.substring(0, 20)}... (truncated)`);\r\n      console.log(`  Version: ${metadata?.version || 'N/A'}`);\r\n      console.log(`  Expires: ${metadata?.expiresOn?.toISOString() || 'Never'}`);\r\n      console.log();\r\n    }\r\n\r\n    // Step 4: Refresh a specific configuration key\r\n    console.log('Step 4: Refreshing a Specific Key');\r\n    console.log('-'.repeat(70));\r\n    \r\n    await config.refreshConfig('ApiKey');\r\n    const refreshedValue = await config.getConfig('ApiKey');\r\n    console.log(`Refreshed ApiKey: ${refreshedValue?.substring(0, 20)}... (truncated)`);\r\n    console.log();\r\n\r\n    // Step 5: Check for expiring secrets\r\n    console.log('Step 5: Checking for Expiring Secrets');\r\n    console.log('-'.repeat(70));\r\n    \r\n    const expiringSecrets = await config.checkHealth();\r\n    if (expiringSecrets.length \u003e 0) {\r\n      console.log('⚠️  WARNING: The following secrets are near expiry:');\r\n      for (const secretName of expiringSecrets) {\r\n        const metadata = config.getProvider().getMetadata(secretName);\r\n        console.log(`  - ${secretName} (expires: ${metadata?.expiresOn?.toISOString()})`);\r\n      }\r\n    } else {\r\n      console.log('✓ All secrets are valid (no expiry warnings)');\r\n    }\r\n    console.log();\r\n\r\n    // Step 6: Demonstrate secret rotation\r\n    console.log('Step 6: Performing Secret Rotation');\r\n    console.log('-'.repeat(70));\r\n    \r\n    const rotationHelper = new SecretRotationHelper(config.getSecretClient());\r\n    \r\n    // Create a new version of a secret\r\n    const secretToRotate = 'AppSecret';\r\n    const newSecretValue = `rotated-value-${Date.now()}`;\r\n    \r\n    console.log(`Rotating secret: ${secretToRotate}`);\r\n    const newVersion = await rotationHelper.rotateSecret(secretToRotate, newSecretValue, {\r\n      expiryDays: 90,\r\n      contentType: 'application/secret',\r\n      tags: {\r\n        rotatedBy: 'demo-script',\r\n        rotatedAt: new Date().toISOString(),\r\n      },\r\n    });\r\n    \r\n    console.log(`✓ New version created: ${newVersion}`);\r\n    console.log();\r\n\r\n    // List all versions\r\n    console.log('Listing all versions of the secret:');\r\n    const versions = await rotationHelper.listVersionsForCleanup(secretToRotate);\r\n    versions.forEach((v, idx) =\u003e {\r\n      console.log(`  ${idx + 1}. Version: ${v.version}`);\r\n      console.log(`     Created: ${v.createdOn?.toISOString() || 'Unknown'}`);\r\n      console.log(`     Expires: ${v.expiresOn?.toISOString() || 'Never'}`);\r\n    });\r\n    console.log();\r\n\r\n    // Step 7: Demonstrate delete and purge (cleanup)\r\n    console.log('Step 7: Demonstrating Delete and Purge Flow');\r\n    console.log('-'.repeat(70));\r\n    console.log('CAUTION: This will permanently delete the secret!');\r\n    console.log('In production, carefully control when to purge secrets.');\r\n    console.log();\r\n    \r\n    // For demo purposes, we'll create a temporary secret and then delete it\r\n    const tempSecretName = `temp-demo-secret-${Date.now()}`;\r\n    console.log(`Creating temporary secret for cleanup demo: ${tempSecretName}`);\r\n    await rotationHelper.rotateSecret(tempSecretName, 'temporary-value', {\r\n      expiryDays: 1,\r\n    });\r\n    console.log();\r\n    \r\n    console.log('Now performing delete and purge...');\r\n    await rotationHelper.deleteAndPurgeSecret(tempSecretName, true);\r\n    console.log();\r\n\r\n    // Step 8: Show cache statistics\r\n    console.log('Step 8: Cache Statistics');\r\n    console.log('-'.repeat(70));\r\n    \r\n    const stats = config.getProvider().getCacheStats();\r\n    console.log(`Cache size: ${stats.size}`);\r\n    console.log(`Cached keys: ${stats.keys.join(', ')}`);\r\n    console.log();\r\n\r\n    console.log('='.repeat(70));\r\n    console.log('Demo Complete!');\r\n    console.log('='.repeat(70));\r\n    console.log();\r\n    console.log('Summary:');\r\n    console.log('✓ Configuration module initialized with managed identity');\r\n    console.log('✓ Bulk-loaded configuration keys at startup');\r\n    console.log('✓ Read values from cache');\r\n    console.log('✓ Refreshed individual keys on demand');\r\n    console.log('✓ Checked for expiring secrets');\r\n    console.log('✓ Rotated a secret (created new version)');\r\n    console.log('✓ Demonstrated safe delete and purge workflow');\r\n    console.log();\r\n\r\n  } catch (error: any) {\r\n    console.error();\r\n    console.error('❌ Error during demo:');\r\n    console.error(error.message);\r\n    console.error();\r\n    \r\n    if (error.code === 'ENOTFOUND' || error.message.includes('vault')) {\r\n      console.error('Hint: Make sure AZURE_KEYVAULT_URL environment variable is set');\r\n      console.error('      Example: https://your-vault-name.vault.azure.net/');\r\n    }\r\n    \r\n    if (error.message.includes('authentication') || error.message.includes('credential')) {\r\n      console.error('Hint: Authentication failed. Make sure you have:');\r\n      console.error('      - Azure CLI installed and logged in (az login)');\r\n      console.error('      - OR running in Azure with managed identity enabled');\r\n      console.error('      - OR appropriate environment variables set');\r\n    }\r\n    \r\n    process.exit(1);\r\n  }\r\n}\r\n\r\n// Run the demo\r\nmain();\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true,\r\n    \"moduleResolution\": \"node\"\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n### SETUP.md\n```\n# Quick Setup Guide\r\n\r\n## Prerequisites\r\n\r\n1. **Node.js** (v16 or higher)\r\n2. **Azure CLI** (for local development)\r\n3. **Azure Key Vault** with secrets configured\r\n\r\n## Setup Steps\r\n\r\n### 1. Install Dependencies\r\n\r\n```bash\r\nnpm install\r\n```\r\n\r\n### 2. Authenticate with Azure (Local Development)\r\n\r\n```bash\r\n# Login to Azure\r\naz login\r\n\r\n# Set your default subscription (optional)\r\naz account set --subscription \"Your-Subscription-Name\"\r\n```\r\n\r\n### 3. Set Environment Variable\r\n\r\n**Linux/macOS:**\r\n```bash\r\nexport AZURE_KEYVAULT_URL=\"https://your-vault-name.vault.azure.net/\"\r\n```\r\n\r\n**Windows PowerShell:**\r\n```powershell\r\n$env:AZURE_KEYVAULT_URL=\"https://your-vault-name.vault.azure.net/\"\r\n```\r\n\r\n**Windows CMD:**\r\n```cmd\r\nset AZURE_KEYVAULT_URL=https://your-vault-name.vault.azure.net/\r\n```\r\n\r\n### 4. Grant Key Vault Access\r\n\r\nEnsure your Azure account or managed identity has the following permissions on the Key Vault:\r\n\r\n```bash\r\n# For local development (using your Azure AD account)\r\naz keyvault set-policy --name your-vault-name \\\r\n  --upn your-email@domain.com \\\r\n  --secret-permissions get list set delete purge\r\n\r\n# For managed identity in Azure\r\naz keyvault set-policy --name your-vault-name \\\r\n  --object-id \u003cmanaged-identity-principal-id\u003e \\\r\n  --secret-permissions get list set delete purge\r\n```\r\n\r\n### 5. Create Sample Secrets\r\n\r\n```bash\r\n# Create test secrets in Key Vault\r\naz keyvault secret set --vault-name your-vault-name \\\r\n  --name DatabaseConnectionString \\\r\n  --value \"Server=myserver;Database=mydb;User=admin;Password=pass123\"\r\n\r\naz keyvault secret set --vault-name your-vault-name \\\r\n  --name ApiKey \\\r\n  --value \"my-api-key-12345\"\r\n\r\naz keyvault secret set --vault-name your-vault-name \\\r\n  --name AppSecret \\\r\n  --value \"my-app-secret-67890\"\r\n\r\n# Optional: Set expiry date (90 days from now)\r\naz keyvault secret set --vault-name your-vault-name \\\r\n  --name ApiKey \\\r\n  --value \"my-api-key-12345\" \\\r\n  --expires \"2026-07-31T00:00:00Z\"\r\n```\r\n\r\n### 6. Build and Run\r\n\r\n```bash\r\n# Build the TypeScript project\r\nnpm run build\r\n\r\n# Run the demo\r\nnpm start\r\n```\r\n\r\n## Running in Azure\r\n\r\nWhen deploying to Azure (App Service, Function App, AKS, VM, etc.):\r\n\r\n### 1. Enable Managed Identity\r\n\r\n```bash\r\n# For App Service / Function App\r\naz webapp identity assign --name your-app-name --resource-group your-rg\r\n\r\n# Get the principal ID from the output\r\n```\r\n\r\n### 2. Grant Key Vault Access to Managed Identity\r\n\r\n```bash\r\naz keyvault set-policy --name your-vault-name \\\r\n  --object-id \u003cmanaged-identity-principal-id\u003e \\\r\n  --secret-permissions get list set delete purge\r\n```\r\n\r\n### 3. Set Environment Variable in App Service\r\n\r\n```bash\r\naz webapp config appsettings set --name your-app-name \\\r\n  --resource-group your-rg \\\r\n  --settings AZURE_KEYVAULT_URL=\"https://your-vault-name.vault.azure.net/\"\r\n```\r\n\r\n## Troubleshooting\r\n\r\n### Authentication Errors\r\n\r\n**Error:** `authentication_failed` or `credential unavailable`\r\n\r\n**Solution:**\r\n- Ensure you're logged in: `az login`\r\n- Verify your account has access to the Key Vault\r\n- Check that the AZURE_KEYVAULT_URL is correct\r\n\r\n### Secret Not Found\r\n\r\n**Error:** `SecretNotFound` or 404\r\n\r\n**Solution:**\r\n- Verify the secret exists: `az keyvault secret list --vault-name your-vault-name`\r\n- Check the secret name spelling\r\n- Ensure you have `get` permission on secrets\r\n\r\n### Permission Denied\r\n\r\n**Error:** `Forbidden` or `insufficient permissions`\r\n\r\n**Solution:**\r\n```bash\r\n# Grant yourself access\r\naz keyvault set-policy --name your-vault-name \\\r\n  --upn $(az account show --query user.name -o tsv) \\\r\n  --secret-permissions get list set delete purge\r\n```\r\n\r\n### Vault URL Issues\r\n\r\n**Error:** `vault not found` or `ENOTFOUND`\r\n\r\n**Solution:**\r\n- Verify the vault exists: `az keyvault show --name your-vault-name`\r\n- Ensure the URL format is correct: `https://vault-name.vault.azure.net/`\r\n- Check network connectivity to Azure\r\n\r\n## Testing Without Azure Key Vault\r\n\r\nIf you want to test the TypeScript compilation without Azure access, you can:\r\n\r\n1. Comment out the demo execution in `src/index.ts`\r\n2. Only build the project: `npm run build`\r\n3. Inspect the generated TypeScript definitions in `dist/`\r\n\r\n## Next Steps\r\n\r\n- Review the [README.md](README.md) for architecture details\r\n- Explore the source files in `src/`\r\n- Customize the configuration for your needs\r\n- Add error handling and logging for production use\r\n- Implement monitoring and alerting for expiring secrets\r\n\n```\n\n### src\\CachedSecretProvider.ts\n```\nimport { SecretProvider, SecretMetadata } from './SecretProvider';\r\n\r\nexport interface CacheEntry {\r\n  metadata: SecretMetadata;\r\n  cachedAt: Date;\r\n}\r\n\r\nexport interface CacheOptions {\r\n  expiryWarningDays?: number;\r\n  autoRefreshNearExpiry?: boolean;\r\n}\r\n\r\nexport class CachedSecretProvider {\r\n  private provider: SecretProvider;\r\n  private cache: Map\u003cstring, CacheEntry\u003e;\r\n  private options: CacheOptions;\r\n\r\n  constructor(provider: SecretProvider, options?: CacheOptions) {\r\n    this.provider = provider;\r\n    this.cache = new Map();\r\n    this.options = {\r\n      expiryWarningDays: 7,\r\n      autoRefreshNearExpiry: true,\r\n      ...options,\r\n    };\r\n  }\r\n\r\n  /**\r\n   * Bulk-loads a predefined set of required config keys at startup\r\n   * @param secretNames Array of secret names to preload\r\n   * @param defaults Optional default values for each secret\r\n   */\r\n  async bulkLoad(secretNames: string[], defaults?: Record\u003cstring, string\u003e): Promise\u003cvoid\u003e {\r\n    console.log(`Bulk loading ${secretNames.length} secrets...`);\r\n    \r\n    const promises = secretNames.map(async (name) =\u003e {\r\n      try {\r\n        const defaultValue = defaults?.[name];\r\n        const secret = await this.provider.getSecret(name, defaultValue);\r\n        \r\n        if (secret) {\r\n          this.cache.set(name, {\r\n            metadata: secret,\r\n            cachedAt: new Date(),\r\n          });\r\n          console.log(`✓ Loaded secret: ${name}`);\r\n        }\r\n      } catch (error: any) {\r\n        console.error(`✗ Failed to load secret '${name}':`, error.message);\r\n      }\r\n    });\r\n\r\n    await Promise.all(promises);\r\n    console.log(`Bulk load complete. ${this.cache.size} secrets in cache.`);\r\n  }\r\n\r\n  /**\r\n   * Gets a secret from cache or fetches it if not cached\r\n   * @param secretName The name of the secret\r\n   * @param defaultValue Default value if secret doesn't exist\r\n   * @returns Secret value or default\r\n   */\r\n  async get(secretName: string, defaultValue?: string): Promise\u003cstring | null\u003e {\r\n    // Check if we should auto-refresh due to near expiry\r\n    if (this.options.autoRefreshNearExpiry \u0026\u0026 this.cache.has(secretName)) {\r\n      const entry = this.cache.get(secretName)!;\r\n      if (await this.shouldRefresh(entry)) {\r\n        console.log(`Auto-refreshing secret '${secretName}' due to near expiry`);\r\n        await this.refresh(secretName, defaultValue);\r\n      }\r\n    }\r\n\r\n    const entry = this.cache.get(secretName);\r\n    if (entry) {\r\n      return entry.metadata.value;\r\n    }\r\n\r\n    // Not in cache, fetch it\r\n    const secret = await this.provider.getSecret(secretName, defaultValue);\r\n    if (secret) {\r\n      this.cache.set(secretName, {\r\n        metadata: secret,\r\n        cachedAt: new Date(),\r\n      });\r\n      return secret.value;\r\n    }\r\n\r\n    return defaultValue || null;\r\n  }\r\n\r\n  /**\r\n   * Forces a refresh of a specific secret from Key Vault\r\n   * @param secretName The name of the secret to refresh\r\n   * @param defaultValue Default value if secret doesn't exist\r\n   */\r\n  async refresh(secretName: string, defaultValue?: string): Promise\u003cvoid\u003e {\r\n    console.log(`Refreshing secret: ${secretName}`);\r\n    const secret = await this.provider.getSecret(secretName, defaultValue);\r\n    \r\n    if (secret) {\r\n      this.cache.set(secretName, {\r\n        metadata: secret,\r\n        cachedAt: new Date(),\r\n      });\r\n      console.log(`✓ Refreshed secret: ${secretName}`);\r\n    } else {\r\n      console.warn(`✗ Could not refresh secret: ${secretName}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Checks if any cached secret is near expiry\r\n   * @returns Array of secret names that are near expiry\r\n   */\r\n  async checkExpiringSecrets(): Promise\u003cstring[]\u003e {\r\n    const expiring: string[] = [];\r\n    \r\n    for (const [name, entry] of this.cache.entries()) {\r\n      if (entry.meta